// gh-1604 items 2+3 — the bench compaction trigger wired through the real
// CLI gates (AC2/AC3 mechanism layer).
//
// `FAH_COMPACT_TRIGGER_TOKENS` fires the auto-compaction at an absolute
// context size (here 24000 on a 200k window, where the default formula
// fires only at 183184) once the run's context crosses it — mirroring a
// bench trial that grows past the trigger mid-run. The compaction event
// lands in the session JSONL, the summarization prompt carries the task
// text (the mechanism that folds it into the rolling summary on real
// runs), and the post-compaction projection still renders the
// obligations ledger block and keeps the latest tool result (protected
// tail). Without the env the same session does not compact at all.
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import 'agent_cli_test_support.dart';

const _window = 200000;
// CompactionSettings.forWindow(200000): reserve 16384 → the DEFAULT
// trigger is 183184 estimated tokens. The bench trigger sits far below.
final _defaultTrigger = _window - 16384;
const _benchTriggerTokens = 24000;

Model get _model => const Model(
  id: 'test-model',
  api: 'test-api',
  provider: 'test-provider',
  baseUrl: 'https://example.test',
  contextWindow: _window,
  maxTokens: 4096,
);

const _taskMarker = 'build the mips interpreter';
const _ledgerText = 'always run the full test suite before pushing';
const _toolResultMarker = 'latest seed tool result';
const _checkpointReply =
    'BENCH CHECKPOINT: the mips task stays open; '
    'folded context summarized here.';
// ~10k estimated tokens: pushes the first turn's context past the 24k
// bench trigger while the boot gate (seed ~16k incl. harness overhead)
// stays under it — the compaction fires MID-RUN, the way a bench trial
// grows past the trigger.
final _bigAnswer = 'growth ${'y' * 40000}';

/// A structured-compaction-aware fake stream: judge calls (the
/// context-hygiene judge prompt) answer `[]` (hide nothing — the passes
/// proceed deterministically), checkpoint calls answer the canned
/// summary, real turns answer from [turnAnswers] in order.
final class _CompactionAwareStream {
  final turnAnswers = <String>[];
  final contexts = <Context>[];
  var _answered = 0;

  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    contexts.add(
      Context(
        systemPrompt: context.systemPrompt,
        messages: List.of(context.messages),
        tools: context.tools,
      ),
    );
    final prompt = [
      for (final m in context.messages)
        switch (m) {
          UserMessage() => messageText(m),
          AssistantMessage() =>
            m.content.whereType<TextContent>().map((b) => b.text).join(),
          _ => '',
        },
    ].join('\n');
    final String reply;
    if (prompt.contains('context-hygiene judge')) {
      reply = '[]';
    } else if (prompt.contains('Write a checkpoint')) {
      reply = _checkpointReply;
    } else {
      reply = turnAnswers[_answered++ % turnAnswers.length];
    }
    final stream = AssistantMessageEventStream();
    for (final event in textTurn(reply)) {
      stream.push(event);
    }
    stream.end();
    return stream;
  }
}

/// [waitForIt] with a LAZY description: the failure text is built at
/// timeout, so it names the state that actually was reached.
Future<void> waitUntil(
  bool Function() condition,
  String Function() describe,
) async {
  for (var i = 0; i < 5000; i++) {
    if (condition()) return;
    await Future<void>.delayed(const Duration(milliseconds: 5));
  }
  fail('timed out waiting: ${describe()}');
}

void main() {
  late FakeCliIO io;

  setUp(() {
    io = FakeCliIO();
  });
  tearDown(() => io.close());

  /// Seeds a resumed session whose transcript (~11k tokens; ~16k with the
  /// harness's own system-prompt/tool overhead) sits UNDER the bench
  /// trigger: the task text rides the first user message, the obligations
  /// ledger carries one open rule, and a valid tool pair (call + result)
  /// is the NEWEST records — the protected tail at compaction time.
  /// The compaction must fire MID-RUN when the big first answer pushes
  /// the context past the trigger — not at boot.
  Future<MemoryExecutionEnv> seedUnderTrigger(String name) async {
    final env = MemoryExecutionEnv(cwd: '/work', shell: FakeShell());
    // Suppress session-start memory maintenance (suite pattern).
    await env.writeFile('/work/.fah/memory/.last_maintenance', '');
    final repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
    final seed = await repo.create(
      JsonlSessionCreateOptions(cwd: '/work', metadata: {'agent': 'cli'}),
    );
    await seed.appendSessionName(name);
    await seed.appendMessage(
      UserMessage.text('TASK $_taskMarker; keep the ledger; ${'task ' * 120}'),
    );
    await seed.appendCustomEntry(
      customType: obligationsLedgerRecordType,
      data: [
        {
          'id': 'obl-test-1',
          'kind': 'owner-rule',
          'text': _ledgerText,
          'sourceRecordId': 'rec-1',
          'createdAt': DateTime.utc(2026).toIso8601String(),
          'status': 'open',
        },
      ],
    );
    for (var i = 0; i < 40; i++) {
      await seed.appendMessage(UserMessage.text('filler$i ${'x' * 1000}'));
    }
    await seed.appendMessage(
      AssistantMessage(
        content: [
          const ToolCall(id: 'call-seed-1', name: 'read', arguments: {}),
        ],
        api: 'test-api',
        provider: 'test-provider',
        model: 'test-model',
        usage: Usage.zero,
        stopReason: StopReason.toolUse,
        timestamp: DateTime.utc(2026),
      ),
    );
    await seed.appendMessage(
      ToolResultMessage(
        toolCallId: 'call-seed-1',
        toolName: 'read',
        content: [const TextContent(text: _toolResultMarker)],
        isError: false,
        timestamp: DateTime.utc(2026),
      ),
    );
    return env;
  }

  AgentCli cli(
    MemoryExecutionEnv env,
    _CompactionAwareStream stream, {
    Map<String, String> environment = const {
      'FAH_COMPACT_TRIGGER_TOKENS': '$_benchTriggerTokens',
    },
  }) => AgentCli(
    config: AgentCliConfig(
      model: _model,
      apiKey: '[REDACTED:Sensitive Value]',
      env: env,
      sessionRoot: '/sessions',
      sessionName: 'bench-trigger-target',
      providerKind: 'openai-completions',
      skillsAccess: SkillsAccess.granted,
    ),
    io: io,
    environment: environment,
    streamFunction: stream.call,
  );

  /// The agent-turn requests (the compaction judge/checkpoint calls are
  /// filtered out by their own system prompts).
  Iterable<Context> turnRequests(_CompactionAwareStream stream) =>
      stream.contexts.where(
        (context) => (context.systemPrompt ?? '').startsWith('You are Fa'),
      );

  test(
    'the bench trigger fires mid-run where the default would not; the '
    'compaction event lands in the JSONL; obligations + latest tool '
    'result survive',
    timeout: const Timeout(Duration(minutes: 5)),
    () async {
      final env = await seedUnderTrigger('bench-trigger-target');
      final stream = _CompactionAwareStream()
        ..turnAnswers.addAll([_bigAnswer, 'second answer']);
      final agent = cli(env, stream);

      final run = agent.run();
      io.sendLine('go');
      await waitUntil(
        () => turnRequests(stream).isNotEmpty && !agent.isBusy,
        () =>
            'turn 1: turns=${turnRequests(stream).length} '
            'calls=${stream.contexts.length}',
      );
      io.sendLine('go');
      await waitUntil(
        () => turnRequests(stream).length >= 2 && !agent.isBusy,
        () =>
            'turn 2: turns=${turnRequests(stream).length} '
            'calls=${stream.contexts.length} '
            'out=${io.out.toString().substring(io.out.length > 2000 ? io.out.length - 2000 : 0)}',
      );
      io.sendLine('/exit');
      await run;

      // The compaction fired MID-RUN (after the first turn), not at boot:
      // the first agent request rode the un-compacted seed — under the
      // DEFAULT trigger (only the bench knob could h…

Now I have a good understanding. Let me plan the fixes per thread:

**Thread 1 (BLOCKING)** — `bench_trigger.dart`: `withCompactionTriggerTokens` throws for `triggerTokens=1` because `clamped ~/ 2 == 0` → `clamp(1, 0)` throws. Fix: `final keep = base.keepRecentTokens.clamp(1, max(1, clamped ~/ 2));` — need `dart:math` import. Add a RED test: `triggerTokens: 1` (also env value `1` through `resolveBenchCompactionSettings`).

Wait, also need to check semantics: for trigger=1: clamped=1, defaultTrigger = 2000-16384 = 183616, clamped < defaultTrigger, so keep = base.keepRecentTokens.clamp(1, max(1, 0)) = clamp(1, 1) = 1. Then reserve = window - 1 = 1999. keep=1. OK, valid.

**Thread 2 (IMPORTANT)** — env knob silently rewrites explicit `config.compactionSettings` override. The PR description says it "wins over defaults but not over an explicit config override". The reviewer says: pick one contract and pin it. Given the PR description states the description contract (config override wins), and the code contradicts it. Which to choose? The reviewer gives both options. Hmm. Think about the intent: `FAH_COMPACT_TRIGGER_TOKENS` is a bench-run knob. An explicit user config `compactionSettings` is a deliberate pin. The PR description already promises "not over an explicit config override". The cleanest fix aligned with the PR description: skip the knob when `override != null` (config override wins), pin with tests including `override.enabled: false`.

Also the `!base.enabled` guard — with `override != null` returning early, the `enabled: false` override case is handled by the early return. But also `resolveBenchCompactionSettings` on a disabled base returns base (guard `if (!base.enabled) return base;`).

Wait — but should the env knob win over an explicit config override instead? Consider: bench runs are unattended; if a user pinned compactionSettings for their local runs, the bench env would override it. The PR description says config wins. The reviewer's first option matches the description. I'll go with "explicit config override wins; the bench env only retunes the defaults" — and update the in-code comment to be unambiguous. This is also the safer contract: a user-pinned config should not be silently rewritten by an env var; and bench operators who need the knob simply don't pin a section.

Add tests in `test/cli/agent_cli_bench_compaction_test.dart`? The reviewer suggests pinning at the `_effectiveCompactionSettings` level. That getter is private in AgentCli. Hmm — is there a test seam? The reviewer says "no test pins either precedence (`agent_cli_bench_compaction_test.dart` builds its config without `compactionSettings`)". We can test via AgentCliConfig with `compactionSettings` set... but `_effectiveCompactionSettings` is private. Is there a `@visibleForTesting` accessor? Let me check. Search for how compactionSettings is exposed in AgentCliConfig and whether tests can observe the effective settings. Maybe via the compaction gates' behavior. Alternatively, pin the precedence at the unit level in bench_trigger_test.dart plus an integration-level check through the CLI. Let me look at AgentCliConfig.compactionSettings and any visibleForTesting seam.

**Thread 3 (SUGGESTION)** — spill.dart: `resolveRunSpillsConfig` drops `base.notes` when env overrides; widen the `attachSpillWiring` notice to cover the override case. Fix:
- In `resolveRunSpillsConfig`, preserve `notes: base.notes` in the composed config (both for the positive-env path). Also maybe add a note about the override? The suggestion says preserve notes and widen notice in agent_cli_spill.dart.
- In `attachSpillWiring`, when `config.spills != null` and env retunes the threshold, print `'[spills] threshold overridden via $spillThresholdEnvVar: ${section.threshold} → ${spills.threshold}'`. Careful: `0` disables — then spills.isActive is false and notice prints. Hmm, in the disabled case (env 0), currently nothing prints at all (no hooks attached). Should we add a notice for disable? The suggestion focuses on the retune case. I could handle: if env set and value == 0 and section existed and was active → note "disabled via env". Let me keep it focused but sensible: compose notice for both override cases.

Let me restructure `attachSpillWiring`:

```dart
