{"command":"python3 - <<'EOF'
import json
starts = {}; groups = {}
n = {'success':0}; fails = []; skipped = 0; cancelled = 0
for l in open('/tmp/full_suite_rerun.json').read().splitlines():
    try: e = json.loads(l)
    except Exception: continue
    t = e.get('type')
    if t == 'testStart': starts[e['test']['id']] = e['test']
    elif t == 'suite': groups[e['suite']['id']] = e['suite']['path']
    elif t == 'testDone':
        r = e.get('result')
        if e.get('hidden'): continue
        if r == 'success': n['success'] += 1
        elif r == 'skipped': skipped += 1
        elif r == 'failure':
            ts = starts.get(e.get('testID'), {})
            fails.append((groups.get(ts.get('suiteID')), str(ts.get('name'))[:120]))
        else:
            cancelled += 1
print('passed:', n['success'], 'skipped:', skipped, 'other:', cancelled)
print('failures:', len(fails))
for f in fails: print(' -', f[0], '::', f[1])
EOF"}

