import json
starts = {}; groups = {}
targets = ('bench_trigger_test', 'shell_job_command_label_test', 'spill_env_test', 'spill_env_wiring_test', 'agent_cli_bench_compaction_test')
res = {}
for l in open('/tmp/full_suite_rerun.json').read().splitlines():
    try: e = json.loads(l)
    except Exception: continue
    t = e.get('type')
    if t == 'testStart': starts[e['test']['id']] = e['test']
    elif t == 'suite': groups[e['suite']['id']] = e['suite']['path']
    elif t == 'testDone':
        ts = starts.get(e.get('testID'), {})
        p = groups.get(ts.get('suiteID'), '')
        if any(x in p for x in targets):
            res.setdefault(p, [0, 0])
            if e.get('result') == 'success': res[p][0] += 1
            else: res[p][1] += 1
for p, (ok, bad) in sorted(res.items()):
    print(f'{p}: {ok} passed, {bad} failed')
EOF"}

