for l in open('/tmp/shard_ab.json').read().splitlines():
    try: e=json.loads(l)
    except: continue
    t=e.get('type')
    if t=='testStart': starts[e['test']['id']]=e['test']
    elif t=='suite': groups[e['suite']['id']]=e['suite']['path']
    elif t=='testDone':
        n+=1
        if e.get('result')!='success' and not e.get('hidden'):
            ts=starts.get(e.get('testID'),{})
            fails.append((e.get('result'), groups.get(ts.get('suiteID')), str(ts.get('name'))[:110]))
print('ab done:', n)
for f in fails: print(f)
""}

