{"command":"python3 -c "
import json
starts={}; groups={}
rows=[]
for l in open('/tmp/shard_aa.json').read().splitlines():
    try: e=json.loads(l)
    except: continue
    t=e.get('type')
    if t=='testStart': starts[e['test']['id']]=e['test']
    elif t=='suite': groups[e['suite']['id']]=e['suite']['path']
    elif t=='testDone':
        ts=starts.get(e.get('testID'),{})
        p=groups.get(ts.get('suiteID'),'')
        if 'agent_cli_bench_compaction' in p:
            rows.append((e.get('result'), str(ts.get('name'))[:95]))
ok=sum(1 for r in rows if r[0]=='success')
print(f'agent_cli_bench_compaction_test: {ok}/{len(rows)} passed')
for r in rows: print(' ', r[0], '|', r[1])
""}

